char crossed[30];
int main(void)
{
    int n, m, count = 0;
    cls();
    for (n = 2; n < 30; n++) {
        if (!crossed[n]) {
            printf("%d ", n);
            count++;
            for (m = n * 2; m < 30; m += n)
                crossed[m] = 1;
        }
    }
    return count;
}
